package jp.tapmarker;
import java.util.concurrent.atomic.AtomicInteger;
public final class CaptureLeaseCompletionTest {
 static int checks;static void check(boolean v,String why){checks++;if(!v)throw new AssertionError(why);}
 public static void main(String[] args){CaptureCircuit c=new CaptureCircuit(2,10000);AtomicInteger callbacks=new AtomicInteger();long first=c.acquire(1,1000);c.releasing(1,first,()->{check(c.active()==0,"release precedes reschedule");callbacks.incrementAndGet();}).run();long next=c.acquire(1,1001);check(next>first,"duplicate does not stall");c.acquire(2,1001);check(c.active()==2,"two lanes bounded");c.releasing(1,first,()->{}).run();check(c.active()==2,"old callback cannot release new lease");c.releasing(1,next,()->{}).run();check(c.active()==1,"other lane retained");long error=c.acquire(1,1002);boolean threw=false;try{c.releasing(1,error,()->{throw new IllegalStateException("rejected");}).run();}catch(IllegalStateException expected){threw=true;}check(threw&&c.active()==1,"exception cannot leak slot");long orphan=c.acquire(1,1003),replacement=c.acquire(1,11003);check(replacement>orphan,"bounded expiry");c.releasing(1,orphan,()->{}).run();check(c.active()==1,"expired callback cannot release replacement");c.reset();c.releasing(1,replacement,()->{}).run();check(c.active()==0&&callbacks.get()==1,"reset does not resurrect slots");System.out.println("CaptureLeaseCompletionTest: "+checks+" passed");}
}
